
const fs = require('fs');
const path = require('path');

const b512 = '';
const b192 = '';
const b180 = '';
const bFav = '';

const publicDir = path.join(process.cwd(), 'public');
if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });

fs.writeFileSync(path.join(publicDir, 'icon-512.png'), Buffer.from(b512, 'base64'));
fs.writeFileSync(path.join(publicDir, 'icon-192.png'), Buffer.from(b192, 'base64'));
fs.writeFileSync(path.join(publicDir, 'apple-touch-icon.png'), Buffer.from(b180, 'base64'));
fs.writeFileSync(path.join(publicDir, 'favicon.ico'), Buffer.from(bFav, 'base64'));

console.log('Icons successfully unpacked from base64 to circumvent Git binary corruption.');
